 "content": "def transform(grid):
    """Return the overlap mask of two equally sized panels separated by a solid line."""
    h, w = len(grid), len(grid[0])
    # A separator is a full row/column of one non-background color, with equal
    # sized nonempty panels on either side.
    for r in range(h):
        vals = set(grid[r])
        if len(vals) == 1 and next(iter(vals)) != 0:
            a, b = grid[:r], grid[r + 1:]
            if r > 0 and len(a) == len(b):
                return [[2 if x != 0 and y != 0 else 0
                         for x, y in zip(a[i], b[i])] for i in range(len(a))]
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1 and next(iter(vals)) != 0:
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            if c > 0 and len(a[0]) == len(b[0]):
                return [[2 if x != 0 and y != 0 else 0
                         for x, y in zip(a[i], b[i])] for i in range(h)]
    raise ValueError("no equal panels separated by a solid nonzero line")

